const dictionarySeeds={"职位类型": ["全职", "实习", "兼职", "外包/合同", "其他"], "办公方式": ["现场办公", "远程", "混合办公"], "招聘角色": ["前端", "后端", "客户端", "测试", "数据", "DevOps", "产品", "设计", "运营", "其他"], "面试职级": ["P2", "P3-1", "P3-2", "P3-3", "P4", "P5"], "面试结论": ["通过", "不通过", "待定/需补充"], "推荐结果": ["推荐", "不推荐", "待补充"], "风险项": ["无", "技术能力", "经验匹配", "沟通协作", "稳定性", "薪资/到岗时间", "其他"], "淘汰原因": ["能力不匹配", "经验不足", "面试表现", "薪资不匹配", "到岗时间不匹配", "职位调整", "其他"], "候选人放弃原因": ["公司取消", "候选人取消", "未到场", "已接受其他机会", "不再求职", "薪资原因", "时间安排", "失联", "个人原因", "其他"], "候选人来源渠道": ["Boss直聘", "内推"]};
let dictionaryCategory='办公方式';
db.dict=Object.entries(dictionarySeeds).flatMap(([category,values])=>values.map((name,index)=>({id:++seq,category,name,order:index+1,enabled:true})));
const who=()=>{const v=profiles[persona],p=db.people.find(p=>p.id===v.id);return {...v,admin:!!v.admin&&p?.roles.includes('管理员'),hr:!!v.hr&&(p?.roles.includes('HR成员')||persona==='both'),manager:!!v.manager&&p?.roles.includes('面试官'),interviewer:!!v.interviewer&&p?.roles.includes('面试官')};},active=c=>!['录用','淘汰','候选人放弃'].includes(c.stage),job=c=>db.jobs.find(j=>j.id===Number(c.job)),person=id=>db.people.find(p=>p.id===id),live=()=>logged&&person(who().id)?.enabled!==false;
function allowed(name){if(!live()||requirePassword)return false;return ['people','departments','dictionary','recycle'].includes(name)?who().admin:['jobs','candidates'].includes(name)?(who().hr||who().manager||who().interviewer):true;}
function visible(c){return live()&&(who().hr||(who().manager&&job(c)?.manager===who().name)||(who().interviewer&&c.sessions.some(s=>s.participants.includes(who().name))));}
function jobs(){return db.jobs.filter(j=>!j.deleted&&(who().hr||(who().manager&&j.manager===who().name)||(who().interviewer&&db.candidates.some(c=>c.job===j.id&&!c.deleted&&visible(c)))));}
const candidates=()=>db.candidates.filter(c=>!c.deleted&&visible(c));
const btn=(text,action,primary=false,disabled='',danger=false)=>`<button ${disabled?'disabled title="'+esc(disabled)+'"':''} class="${primary?'primary':''} ${danger?'danger':''}" data-action="${esc(action)}">${esc(text)}</button>`;
const link=(text,to)=>`<a href="#${esc(to)}">${esc(text)}</a>`;
const pill=(text,gray=false)=>`<span class="pill ${gray?'gray':['录用','通过','启用','可招聘'].includes(text)?'green':['待筛选','待决策'].includes(text)?'orange':''}">${esc(text)}</span>`;
const facts=obj=>`<div class="facts">${Object.entries(obj).map(([k,v])=>`<div class="fact"><span>${esc(k)}</span><b>${esc(v)}</b></div>`).join('')}</div>`;
function heading(title,sub='',actions=''){return `<div class="page-head"><div><h1>${esc(title)}</h1><p class="subtitle">${esc(sub)}</p></div><div class="actions">${actions}</div></div>`;}
const card=(title,body,actions='')=>`<section class="card"><div class="card-head"><h2>${esc(title)}</h2><div class="actions">${actions}</div></div>${body}</section>`;
function field(name,label,type='text',value='',options=[],required=true,hint='',disabled=false){const uid='field-'+(++fieldSequence);let control;if(type==='select')control=`<select name="${name}" ${required?'required':''} ${disabled?'disabled':''}><option value="">请选择</option>${options.map(x=>`<option value="${esc(x)}" ${String(value)===String(x)?'selected':''}>${esc(x)}</option>`).join('')}</select>`;else if(type==='textarea')control=`<textarea name="${name}" ${required?'required':''} maxlength="2000">${esc(value)}</textarea>`;else if(type==='checks')control=`<div class="check-group">${options.map(x=>`<label><input type="checkbox" name="${name}" value="${esc(x)}" ${(Array.isArray(value)?value:[]).includes(x)?'checked':''}>${esc(x)}</label>`).join('')}</div>`;else control=`<input name="${name}" type="${type}" value="${type==='file'||type==='password'?'':esc(value)}" ${required?'required':''} ${disabled?'disabled':''} ${type==='number'?'min="1" max="9999" step="1"':type==='file'?'accept=".pdf,.doc,.docx"':type==='password'?'minlength="15" maxlength="128"':type==='text'?'maxlength="100"':''}>`;control=control.replace(/<(input|select|textarea)\b/,`<$1 id="${uid}" ${hint?'aria-describedby="'+uid+'-hint"':''}`);return `<div class="field ${type==='textarea'?'wide':''}"><label ${type==='checks'?'':'for="'+uid+'"'}>${esc(label)}${required?'<span class="required">*</span>':''}</label>${control}${hint?`<small class="hint" id="${uid}-hint">${esc(hint)}</small>`:''}</div>`;}
function form(kind,id,body,extra=''){return `<form id="page-form" data-kind="${kind}" data-id="${id||''}"><section class="card"><div class="fields">${body}</div>${extra}<p id="form-error" class="error" role="alert"></p><div class="form-footer">${btn('取消','cancel-form') }<button class="primary" type="submit">保存</button></div></section></form>`;}
function table(cols,rows){return `<div class="table-wrap"><table><thead><tr>${cols.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;}
const row=cells=>'<tr>'+cells.map(x=>'<td>'+x+'</td>').join('')+'</tr>';
function list(name,title,sub,cols,items,makeRow,actions='',opts=[]){let q=query[name]??={search:'',filter:'',size:20,page:1};let filtered=items.filter(x=>(!q.job||x.job===q.job)&&((name==='dictionary'?x.name:JSON.stringify(x)).toLowerCase().includes(q.search.toLowerCase()))&&(!q.filter||[x.stage,x.dept,x.type,...(typeof x.read==='boolean'?[x.read?'已读':'未读']:[]),x.enabled?'启用':'停用',x.enabled?'可招聘':'已关闭',...(x.roles||[])].includes(q.filter)));if(name==='people')filtered=filtered.filter(x=>(!q.department||x.dept===q.department)&&(!q.role||x.roles.includes(q.role))&&(!q.status||x.enabled===(q.status==='启用')));if(mode==='empty')filtered=[];const total=filtered.length;const pages=Math.max(1,Math.ceil(total/q.size));q.page=Math.min(q.page,pages);return (name==='workbench'?'':heading(title,sub,actions))+`<section class="card"><div class="toolbar"><input aria-label="搜索" id="search" placeholder="搜索${esc(title.replace('列表',''))}" value="${esc(q.search)}"><select aria-label="筛选" id="filter" ${name==='people'?'hidden':''}><option value="">全部</option>${opts.map(x=>`<option ${q.filter===x?'selected':''}>${esc(x)}</option>`).join('')}</select>${name==='people'?[['department','部门',db.departments.map(x=>x.name)],['role','角色',roles()],['status','账号状态',['启用','禁用']]].map(([key,label,values])=>`<label class="filter-field">${label}<select id="filter-${key}" aria-label="${label}"><option value="">全部</option>${values.map(v=>`<option value="${esc(v)}" ${q[key]===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`).join(''):''}${btn('查询','query:'+name)}${btn('重置','clear:'+name)}${q.job?'<span class="pill">职位：'+esc(db.jobs.find(j=>j.id===q.job)?.name)+'</span>':''}</div>${mode==='error'?'<div class="empty"><h2>加载失败</h2><p>请重试，原查询条件已保留。</p>'+btn('重试','retry')+'</div>':!total?'<div class="empty"><h2>暂无符合条件的记录</h2><p>可调整查询条件后重试。</p></div>':table(cols,filtered.slice((q.page-1)*q.size,q.page*q.size).map(makeRow))}<div class="pagination">共 ${total} 条 <select id="page-size" aria-label="每页条数">${[20,50,100].map(n=>`<option value="${n}" ${n===q.size?'selected':''}>${n}条／页</option>`).join('')}</select>${btn('上一页','page:'+name+':-1',false,q.page===1?'已是第一页':'')}第 ${q.page} / ${pages} 页${btn('下一页','page:'+name+':1',false,q.page===pages?'已是最后一页':'')}</div></section>`;}
function go(to,remember=true){if(dirty&&!confirm('未保存的修改将丢失，是否放弃离开？'))return;dirty=false;if(remember)origin[to]=location.hash.slice(1)||'/workbench';location.hash=to;}
function back(fallback){go(origin[location.hash.slice(1)]||fallback,false);}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2600);}
function log(action,target){db.audit.unshift({id:++seq,name:who().name,action,target,time:new Date().toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}),domain:['人员','部门','字典','账号','角色'].some(x=>action.includes(x))?'平台':'招聘'});}
function modal(title,body,submit,label='保存',drawer=false){$('#modal').className=drawer?'drawer':'';$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;$('#modal-error').textContent='';$('#modal-save').textContent=label;$('#modal-save').hidden=!submit;modalSubmit=submit;modalDirty=false;$('#modal').showModal();}
function closeModal(){if(modalDirty&&modalSubmit&&!confirm('未保存的修改将丢失，是否放弃？'))return;$('#modal').close();modalDirty=false;}
function confirmed(title,body,run,reason=true){modal(title,`<p>${esc(body)}</p>${reason?field('reason','原因','textarea'):''}<label><input name="confirmed" type="checkbox" required> 我已确认目标及上述影响</label>`,d=>{if(reason&&!d.get('reason')?.trim())throw Error('请填写原因');run(d);},'确认');}
function roles(){return ['HR成员','面试官','管理员'];}
function deptOptions(current=''){return db.departments.filter(x=>x.enabled||x.name===current).map(x=>x.name);}
function peopleForm(p){return heading(p?'编辑人员':'新增人员','人员身份与关联账号统一维护')+form('people',p?.id,field('name','姓名','text',p?.name)+field('email','邮箱','email',p?.email)+field('dept','所属部门','select',p?.dept,deptOptions(p?.dept))+ (p?field('roles','当前角色','text',p.roles.join('、'),[],false,'通过人员详情“编辑角色”修改',true)+field('reason','邮箱变更原因','textarea','',[],false,'邮箱发生变化时必填；使原会话失效'):field('roles','角色','checks',[],roles())+field('password','临时密码','password','',[],true,'15–128个字符；首次登录需改密')));}
