if(act==='view-evaluation'){if(!s)return;modal('评价详情',s.evaluations.map(e=>facts({'作者':e.author,'结论':e.conclusion,'推荐':e.recommend,'风险':e.risk||'无','修改人':e.modifiedBy||'—','历史版本':e.previous?'保留原版本':'首次版本'})).join(''),null,'',true);return;}
