if(act==='hire'){if(!who().hr||c.stage!=='待决策'||c.source==='内推')return;confirmed('确认录用','请确认已与候选人确认可入职；Boss渠道沿用Boss确认，内推确认方式待业务落实。本次操作终止活动任务，结果不可回退。',()=>{c.stage='录用';log('确认录用','候选人 '+id);},false);return;}
